package org.apache.commons.math3.genetics;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collection;
import java.util.Collections;
import java.util.Iterator;
import java.util.List;
import org.apache.commons.math3.exception.NotPositiveException;
import org.apache.commons.math3.exception.NullArgumentException;
import org.apache.commons.math3.exception.NumberIsTooLargeException;
import org.apache.commons.math3.exception.NumberIsTooSmallException;
import org.apache.commons.math3.exception.util.LocalizedFormats;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * Unit tests for ListPopulation.iterator().
 */
public class ListPopulation_iterator_TriageGen1Test {

    /**
     * Mock implementation of Chromosome to facilitate testing.
     */
    private static class MockChromosome implements Chromosome {
        @Override
        public double getFitness() {
            return 1.0;
        }

        @Override
        public Chromosome copy() {
            return new MockChromosome();
        }
    }

    @Test
    public void testIteratorEmptyPopulation() {
        int limit = 10;
        ListPopulation population = new ListPopulation(limit);

        Iterator<Chromosome> iterator = population.iterator();

        assertNotNull("Iterator should not be null", iterator);
        assertFalse("Iterator of empty population should not have next", iterator.hasNext());
    }

    @Test
    public void testIteratorWithPopulatedPopulation() {
        int limit = 10;
        Chromosome c1 = new MockChromosome();
        Chromosome c2 = new MockChromosome();
        List<Chromosome> list = Arrays.asList(c1, c2);

        ListPopulation population = new ListPopulation(list, limit);

        Iterator<Chromosome> iterator = population.iterator();

        assertNotNull("Iterator should not be null", iterator);
        assertTrue("Iterator should have elements", iterator.hasNext());

        int count = 0;
        while (iterator.hasNext()) {
            Chromosome c = iterator.next();
            assertNotNull(c);
            count++;
            // Verify we get the exact same instances
            if (count == 1) {
                assertEquals("First element mismatch", c1, c);
            } else if (count == 2) {
                assertEquals("Second element mismatch", c2, c);
            }
        }
        assertEquals("Iterator should have returned exactly 2 elements", 2, count);
    }

    @Test
    public void testIteratorAfterAddingChromosomes() {
        int limit = 5;
        ListPopulation population = new ListPopulation(limit);
        Chromosome c1 = new MockChromosome();

        population.addChromosome(c1);

        Iterator<Chromosome> iterator = population.iterator();

        assertTrue(iterator.hasNext());
        assertEquals("Should return the added chromosome", c1, iterator.next());
        assertFalse(iterator.hasNext());
    }

    @Test
    public void testIteratorAfterSetChromosomes() {
        int limit = 5;
        ListPopulation population = new ListPopulation(limit);

        Chromosome c1 = new MockChromosome();
        Chromosome c2 = new MockChromosome();
        List<Chromosome> newList = new ArrayList<>();
        newList.add(c1);
        newList.add(c2);

        population.setChromosomes(newList);

        Iterator<Chromosome> iterator = population.iterator();

        int count = 0;
        while (iterator.hasNext()) {
            iterator.next();
            count++;
        }
        assertEquals("Iterator should reflect the newly set list size", 2, count);
    }
}
